module Top;
    string sq[$] = '{"ab", "c", "def"};
    string s;
    function automatic string joined(input string items[$]);
        joined = {>>{items}};
    endfunction
    initial begin
        s = {>>{sq}};
        $display("s=\"%s\" len=%0d eq=%0d", s, s.len(), s == "abcdef");
        s = joined(sq);
        $display("joined len=%0d eq=%0d", s.len(), s == "abcdef");
    end
endmodule
